import{_ as a,o as e,c as n,a4 as t}from"./chunks/framework.DAe4SYBh.js";const h=JSON.parse('{"title":"nfs 安装和使用","description":"","frontmatter":{},"headers":[],"relativePath":"technology/linux_server/nfs安装和使用.md","filePath":"technology/linux_server/nfs安装和使用.md"}'),i={name:"technology/linux_server/nfs安装和使用.md"};function p(l,s,o,r,d,c){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="nfs-安装和使用" tabindex="-1">nfs 安装和使用 <a class="header-anchor" href="#nfs-安装和使用" aria-label="Permalink to “nfs 安装和使用”">​</a></h1><p>固定端口</p><p><code>vim /etc/default/nfs-kernel-server</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>RPCMOUNTDOPTS=&quot;--manage-gids --port &lt;mountd_port_number&gt;&quot;</span></span>
<span class="line"><span>RPCNLOCKDOPTS=&quot;--port &lt;nlockmgr_port_number&gt;&quot;</span></span>
<span class="line"><span>RPCRQUOTADOPTS=&quot;--port &lt;rquotad_port_number&gt;&quot;</span></span></code></pre></div><p><code>systemctl restart nfs-kernel-server</code></p><p>查看 rpc 端口情况</p><p><code>rpcinfo -p</code></p><p>防火墙，nlockmgr 端口根据实际情况，mountd 端口使用上面固定的</p><blockquote><p>TCP/UDP 端口 2049： 这是 NFS 服务器上的主要端口，用于 NFS 数据传输和挂载。</p><p>UDP 端口 111： 这是 RPC (Remote Procedure Call) 绑定端口，NFS 使用它来注册 RPC 服务。</p><p>UDP 端口 32765 至 32768： 这是 NFS 的动态端口范围，用于一些辅助协议，如 NFS 锁管理（nlockmgr）和远程配额（rquotad）</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow 2049/tcp</span></span>
<span class="line"><span>sudo ufw allow 2049/udp</span></span>
<span class="line"><span>sudo ufw allow 111/udp</span></span>
<span class="line"><span>sudo ufw allow 32765:32768/udp</span></span>
<span class="line"><span>sudo ufw reload</span></span></code></pre></div><p>挂载</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mount -t nfs -o nolock 192.168.0.111:/mnt/sdc1/work/project/rp /mnt/nfs</span></span></code></pre></div><p>卸载</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo umount /mnt/nfs</span></span></code></pre></div>`,14)])])}const g=a(i,[["render",p]]);export{h as __pageData,g as default};
